head.b:skin:
:root {
  --vb-bg: #07080D;
  --vb-surface: #0D101B;
  --vb-surface-2: #121626;
  --vb-border: rgba(255, 255, 255, 0.10);
  --vb-text: #F8FAFC;
  --vb-muted: #94A3B8;
  --vb-dim: #64748B;
  --vb-purple: #9333EA;
  --vb-purple-bright: #C084FC;
  --vb-blue: #2563EB;
  --vb-blue-bright: #38BDF8;
  --vb-pink: #EC4899;
  --vb-font-display: 'Outfit', system-ui, -apple-system, sans-serif;
  --vb-font-sans: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  --vb-font-mono: 'JetBrains Mono', ui-monospace, SFMono-Regular, monospace;
}

*, *::before, *::after { box-sizing: border-box; }
html {
  background-color: var(--vb-bg);
  color: var(--vb-text);
  font-family: var(--vb-font-sans);
  scroll-behavior: smooth;
}
body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  background-color: var(--vb-bg);
  color: var(--vb-text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; border: 0; background: transparent; color: inherit; }
input { font-family: inherit; }
h1, h2, h3, .vb-display { font-family: var(--vb-font-display); margin: 0; }
.vb-mono { font-family: var(--vb-font-mono); font-variant-numeric: tabular-nums; }
:focus-visible { outline: 2px solid var(--vb-blue-bright); outline-offset: 2px; }

/* Top Header */
.vb-header {
  position: sticky;
  top: 0;
  z-index: 40;
  border-bottom: 1px solid var(--vb-border);
  background: rgba(7, 8, 13, 0.90);
  backdrop-filter: blur(12px);
}
.vb-header-inner {
  max-width: 80rem;
  margin: 0 auto;
  padding: 0.875rem 1.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5rem;
}
.vb-logo {
  font-family: var(--vb-font-display);
  font-size: 1.35rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  white-space: nowrap;
  flex-shrink: 0;
  background: linear-gradient(90deg, #C084FC, #A855F7, #38BDF8);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.vb-nav {
  display: none;
  align-items: center;
  gap: 1.5rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--vb-muted);
}
.vb-nav-btn {
  white-space: nowrap;
  flex-shrink: 0;
  padding: 0.25rem 0;
  transition: color 150ms ease;
}
.vb-nav-btn:hover, .vb-nav-btn.is-active { color: #FFFFFF; }
.vb-nav-btn.is-active {
  text-decoration: underline;
  text-decoration-color: #A855F7;
  text-decoration-thickness: 2px;
  text-underline-offset: 8px;
}
.vb-header-actions {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  flex-shrink: 0;
}
.vb-search-btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.875rem;
  border-radius: 0.5rem;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(255,255,255,0.05);
  font-size: 0.75rem;
  font-weight: 600;
  color: #FFFFFF;
  white-space: nowrap;
}
.vb-search-btn:hover { border-color: #A855F7; background: rgba(255,255,255,0.10); }
.vb-menu-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.45rem 0.65rem;
  border-radius: 0.5rem;
  border: 1px solid rgba(255,255,255,0.16);
  color: #FFFFFF;
}
.vb-mobile-drawer {
  display: none;
  border-top: 1px solid var(--vb-border);
  background: #0B0D15;
  padding: 1rem 1.25rem;
  flex-direction: column;
  gap: 0.65rem;
}
.vb-mobile-drawer.is-open { display: flex; }
.vb-mobile-drawer button, .vb-mobile-drawer a {
  text-align: left;
  padding: 0.4rem 0;
  font-size: 0.9rem;
  font-weight: 500;
  color: #E2E8F0;
}

/* Main Container */
.vb-main {
  flex: 1;
  width: 100%;
  max-width: 80rem;
  margin: 0 auto;
  padding: 2rem 1.25rem 3rem;
}

/* Hero Stage */
.vb-hero {
  position: relative;
  overflow: hidden;
  border-radius: 1.5rem;
  border: 1px solid var(--vb-border);
  background: linear-gradient(135deg, #121324 0%, #0B0D16 55%, #080A12 100%);
  padding: 1.5rem;
}
.vb-glow-1, .vb-glow-2 {
  position: absolute;
  width: 18rem;
  height: 18rem;
  border-radius: 999px;
  pointer-events: none;
  filter: blur(56px);
}
.vb-glow-1 { top: -6rem; right: -6rem; background: rgba(147, 51, 234, 0.22); }
.vb-glow-2 { bottom: -6rem; left: -6rem; background: rgba(37, 99, 235, 0.20); }
.vb-hero-grid {
  position: relative;
  z-index: 2;
  display: grid;
  grid-template-columns: 1fr;
  gap: 2rem;
  align-items: center;
}
.vb-hero-left {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  align-items: flex-start;
}
.vb-art {
  position: relative;
  flex-shrink: 0;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.16);
  background: linear-gradient(135deg, #9333EA, #2563EB);
  box-shadow: 0 12px 30px rgba(0,0,0,0.45);
  display: flex;
  align-items: center;
  justify-content: center;
}
.vb-art.is-playing {
  border-color: rgba(168, 85, 247, 0.75);
  box-shadow: 0 12px 32px rgba(147, 51, 234, 0.32);
}
.vb-art img { width: 100%; height: 100%; object-fit: cover; display: block; }
.vb-art-sm { width: 3rem; height: 3rem; border-radius: 0.5rem; font-size: 0.75rem; }
.vb-art-md { width: 4rem; height: 4rem; border-radius: 0.75rem; font-size: 0.875rem; }
.vb-art-xl { width: 14rem; height: 14rem; border-radius: 1.5rem; font-size: 2rem; }
.vb-art-fallback { font-family: var(--vb-font-display); font-weight: 700; color: rgba(255,255,255,0.9); align-items: center; justify-content: center; }

.vb-kicker {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  color: var(--vb-blue-bright);
}
.vb-hero-title {
  margin-top: 0.5rem;
  font-size: 2rem;
  line-height: 1.1;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: #FFFFFF;
}
.vb-hero-sub {
  margin-top: 0.75rem;
  font-size: 0.95rem;
  color: #CBD5E1;
}
.vb-official-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  margin-top: 0.4rem;
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--vb-blue-bright);
}
.vb-official-link:hover { text-decoration: underline; }

.vb-btn-row {
  margin-top: 1.4rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  align-items: center;
}
.vb-btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.85rem 1.65rem;
  border-radius: 0.75rem;
  background: linear-gradient(90deg, #9333EA, #2563EB);
  color: #FFFFFF;
  font-size: 0.875rem;
  font-weight: 700;
  box-shadow: 0 10px 24px rgba(147, 51, 234, 0.32);
  white-space: nowrap;
  transition: filter 150ms ease, transform 120ms ease;
}
.vb-btn-primary:hover { filter: brightness(1.1); }
.vb-btn-primary:active { transform: scale(0.97); }
.vb-btn-sec {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.85rem 1rem;
  border-radius: 0.75rem;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(255,255,255,0.05);
  color: #FFFFFF;
  font-size: 0.875rem;
  font-weight: 600;
  white-space: nowrap;
}
.vb-btn-sec:hover { background: rgba(255,255,255,0.11); }
.vb-btn-sec.is-on {
  border-color: var(--vb-blue-bright);
  background: rgba(37, 99, 235, 0.22);
}

.vb-engine-switch {
  margin-top: 1rem;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  color: var(--vb-muted);
}
.vb-engine-switch button { font-weight: 600; color: var(--vb-muted); }
.vb-engine-switch button.is-active {
  color: #FFFFFF;
  text-decoration: underline;
  text-decoration-color: #38BDF8;
  text-underline-offset: 4px;
}

/* Visualizer */
.vb-vis-box {
  position: relative;
  height: 13.5rem;
  overflow: hidden;
  border-radius: 1rem;
  border: 1px solid var(--vb-border);
  background: #0B0D15;
}
.vb-vis-canvas { width: 100%; height: 100%; display: block; }
.vb-vis-caption {
  position: absolute;
  bottom: 0.6rem;
  left: 0.85rem;
  font-size: 0.7rem;
  color: var(--vb-muted);
  pointer-events: none;
}
.vb-vis-modes {
  margin-top: 0.75rem;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.vb-vis-mode-btn {
  padding: 0.38rem 0.75rem;
  border-radius: 0.5rem;
  border: 1px solid var(--vb-border);
  background: rgba(255,255,255,0.05);
  color: var(--vb-muted);
  font-size: 0.75rem;
  font-weight: 500;
}
.vb-vis-mode-btn.is-active {
  border-color: transparent;
  background: linear-gradient(90deg, #9333EA, #2563EB);
  color: #FFFFFF;
}

/* Section Headings & Grids */
.vb-section { margin-top: 3rem; }
.vb-section-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
}
.vb-section-head h2 { font-size: 1.5rem; font-weight: 700; color: #FFFFFF; }
.vb-section-head p { margin: 0.3rem 0 0; font-size: 0.875rem; color: var(--vb-muted); }
.vb-link-more { font-size: 0.875rem; font-weight: 600; color: var(--vb-blue-bright); white-space: nowrap; }
.vb-link-more:hover { color: #FFFFFF; }

.vb-grid-5 {
  margin-top: 1.25rem;
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 1rem;
}
.vb-grid-4 {
  margin-top: 1.25rem;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.875rem;
}
.vb-grid-3 {
  margin-top: 0.875rem;
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr));
  gap: 1rem;
}

.vb-card {
  border-radius: 1rem;
  border: 1px solid var(--vb-border);
  background: var(--vb-surface);
  padding: 1rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  transition: border-color 150ms ease, box-shadow 150ms ease;
}
.vb-card:hover { border-color: rgba(255,255,255,0.24); }
.vb-card.is-active {
  border-color: #A855F7;
  box-shadow: 0 10px 26px rgba(147, 51, 234, 0.22);
}
.vb-card-row { flex-direction: row; align-items: center; gap: 0.875rem; }
.vb-card-title { font-family: var(--vb-font-display); font-size: 1rem; font-weight: 700; color: #FFFFFF; }
.vb-card-sub {
  margin-top: 0.25rem;
  font-size: 0.75rem;
  color: var(--vb-muted);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.vb-card-meta { margin-top: 0.7rem; font-size: 0.7rem; color: var(--vb-dim); }

.vb-play-circle {
  width: 2.35rem;
  height: 2.35rem;
  border-radius: 999px;
  background: rgba(255,255,255,0.10);
  color: #FFFFFF;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 150ms ease;
}
.vb-play-circle:hover { background: linear-gradient(90deg, #9333EA, #2563EB); }

/* Track Rows */
.vb-tracklist {
  margin-top: 1.25rem;
  border-radius: 1rem;
  border: 1px solid var(--vb-border);
  background: var(--vb-surface);
  overflow: hidden;
}
.vb-track-row {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 0.9rem 1rem;
  border-bottom: 1px solid var(--vb-border);
  transition: background 150ms ease;
}
.vb-track-row:last-child { border-bottom: 0; }
.vb-track-row:hover { background: rgba(255,255,255,0.035); }
.vb-track-row.is-current { background: rgba(147, 51, 234, 0.14); }
.vb-track-left { display: flex; align-items: center; gap: 0.875rem; min-width: 0; flex: 1; }
.vb-track-num { width: 1.5rem; flex-shrink: 0; font-size: 0.75rem; color: var(--vb-dim); }
.vb-track-info { min-width: 0; flex: 1; }
.vb-track-title {
  display: block;
  width: 100%;
  text-align: left;
  font-size: 0.875rem;
  font-weight: 600;
  color: #FFFFFF;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.vb-track-row.is-current .vb-track-title { color: var(--vb-purple-bright); }
.vb-track-artist {
  font-size: 0.75rem;
  color: #CBD5E1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.vb-track-meta {
  margin-top: 0.15rem;
  font-size: 0.7rem;
  color: var(--vb-muted);
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
}
.vb-track-right {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding-left: 2.35rem;
  flex-shrink: 0;
}
.vb-track-play-btn {
  padding: 0.4rem 0.8rem;
  border-radius: 0.5rem;
  background: rgba(255,255,255,0.10);
  font-size: 0.75rem;
  font-weight: 600;
  color: #FFFFFF;
}
.vb-track-play-btn:hover { background: linear-gradient(90deg, #9333EA, #2563EB); }

/* Search & Forms */
.vb-input-box {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  border-radius: 1rem;
  border: 1px solid rgba(255,255,255,0.16);
  background: var(--vb-surface);
  padding: 0.85rem 1rem;
}
.vb-input-box:focus-within { border-color: #A855F7; }
.vb-input-box input, .vb-text-input {
  width: 100%;
  border: 0;
  background: transparent;
  color: #FFFFFF;
  font-size: 0.9rem;
  outline: none;
}
.vb-text-input {
  border-radius: 0.6rem;
  border: 1px solid rgba(255,255,255,0.16);
  background: rgba(255,255,255,0.05);
  padding: 0.55rem 0.75rem;
  font-size: 0.8rem;
}

/* Blogger Posts & Pages */
.vb-blog-wrap { margin-top: 2.5rem; }
.vb-post-card {
  border-radius: 1.25rem;
  border: 1px solid var(--vb-border);
  background: var(--vb-surface);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
}
.vb-post-title { font-size: 1.75rem; font-weight: 800; color: #FFFFFF; line-height: 1.2; }
.vb-post-meta { margin-top: 0.5rem; font-size: 0.8rem; color: var(--vb-muted); }
.vb-post-body { margin-top: 1.25rem; font-size: 0.95rem; line-height: 1.75; color: #E2E8F0; }
.vb-post-body img { max-width: 100%; height: auto; border-radius: 0.75rem; margin: 1rem 0; }
.vb-post-body a { color: var(--vb-blue-bright); text-decoration: underline; }
.vb-post-labels { margin-top: 1.25rem; font-size: 0.8rem; color: var(--vb-muted); }
.vb-post-labels a { color: var(--vb-purple-bright); margin-right: 0.65rem; }
.vb-comments-box {
  margin-top: 1.5rem;
  border-top: 1px solid var(--vb-border);
  padding-top: 1.25rem;
}
.vb-comment-item {
  padding: 0.85rem 0;
  border-bottom: 1px solid var(--vb-border);
  font-size: 0.875rem;
}

/* Persistent YouTube Dock */
.vb-yt-dock {
  position: fixed;
  right: 1rem;
  bottom: 5.75rem;
  z-index: 35;
  width: 17.5rem;
  overflow: hidden;
  border-radius: 1rem;
  border: 1px solid rgba(255,255,255,0.18);
  background: rgba(10, 12, 20, 0.96);
  box-shadow: 0 18px 40px rgba(0,0,0,0.65);
  transition: opacity 180ms ease;
}
.vb-yt-dock.is-hidden {
  pointer-events: none;
  opacity: 0;
  z-index: -1;
  width: 200px;
}
.vb-yt-dock-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.4rem 0.7rem;
  border-bottom: 1px solid var(--vb-border);
  font-size: 0.7rem;
  color: #CBD5E1;
}
.vb-yt-frame-wrap { aspect-ratio: 16 / 9; width: 100%; background: #000000; }

/* Persistent Bottom Player Bar */
.vb-player {
  position: fixed;
  inset-inline: 0;
  bottom: 0;
  z-index: 45;
  border-top: 1px solid rgba(255,255,255,0.14);
  background: rgba(9, 11, 18, 0.96);
  backdrop-filter: blur(18px);
}
.vb-player-inner {
  max-width: 80rem;
  margin: 0 auto;
  padding: 0.65rem 1rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.875rem;
}
.vb-player-left { display: flex; align-items: center; gap: 0.75rem; min-width: 0; flex: 1; }
.vb-player-center { display: flex; flex-direction: column; align-items: center; gap: 0.35rem; }
.vb-transport { display: flex; align-items: center; gap: 0.6rem; }
.vb-play-fab {
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 999px;
  background: linear-gradient(90deg, #9333EA, #2563EB);
  color: #FFFFFF;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 8px 20px rgba(147, 51, 234, 0.35);
}
.vb-timeline { display: none; width: 100%; align-items: center; gap: 0.6rem; font-size: 0.7rem; color: var(--vb-muted); }
.vb-player-right { display: flex; align-items: center; justify-content: flex-end; gap: 0.55rem; }
.vb-hide-sm { display: none; }
.vb-hide-xl { display: none; }

input[type='range'].vb-slider {
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  cursor: pointer;
}
input[type='range'].vb-slider::-webkit-slider-runnable-track {
  height: 5px;
  border-radius: 999px;
  background: rgba(255,255,255,0.16);
}
input[type='range'].vb-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 13px;
  height: 13px;
  margin-top: -4px;
  border-radius: 999px;
  background: #F8FAFC;
  box-shadow: 0 0 8px rgba(168, 85, 247, 0.65);
}

/* Queue & Settings Drawer */
.vb-drawer {
  display: none;
  position: fixed;
  inset-inline: 0.75rem;
  bottom: 5.5rem;
  z-index: 44;
  max-width: 48rem;
  margin: 0 auto;
  max-height: 68vh;
  overflow-y: auto;
  border-radius: 1.25rem;
  border: 1px solid rgba(255,255,255,0.18);
  background: rgba(13, 16, 27, 0.97);
  padding: 1.25rem;
  box-shadow: 0 24px 60px rgba(0,0,0,0.7);
  backdrop-filter: blur(20px);
}
.vb-drawer.is-open { display: block; }

.vb-notice {
  display: none;
  position: fixed;
  left: 1rem;
  bottom: 6rem;
  z-index: 50;
  max-width: 26rem;
  border-radius: 1rem;
  border: 1px solid rgba(251, 191, 36, 0.45);
  background: rgba(19, 17, 28, 0.96);
  padding: 0.9rem 1rem;
  font-size: 0.75rem;
  color: #F8FAFC;
  box-shadow: 0 18px 40px rgba(0,0,0,0.65);
}
.vb-notice.is-open { display: block; }

/* Footer */
.vb-footer {
  border-top: 1px solid var(--vb-border);
  background: #05060A;
  padding: 2.25rem 1.25rem 8rem;
  font-size: 0.75rem;
  color: var(--vb-muted);
}
.vb-footer-inner {
  max-width: 80rem;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}
.vb-footer-links { display: flex; flex-wrap: wrap; gap: 1.25rem; }
.vb-footer-links a:hover, .vb-footer-links button:hover { color: #FFFFFF; }

/* Responsive Breakpoints */
@media (min-width: 640px) {
  .vb-hero { padding: 2.25rem; }
  .vb-hero-left { flex-direction: row; align-items: center; }
  .vb-art-xl { width: 16rem; height: 16rem; }
  .vb-hero-title { font-size: 2.75rem; }
  .vb-grid-5 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .vb-grid-3 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .vb-track-row { flex-direction: row; align-items: center; justify-content: space-between; }
  .vb-track-right { padding-left: 0; }
  .vb-hide-sm { display: inline-flex; }
}
@media (min-width: 768px) {
  .vb-nav { display: flex; }
  .vb-menu-btn { display: none; }
  .vb-grid-4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .vb-footer-inner { flex-direction: row; align-items: center; justify-content: space-between; }
}
@media (min-width: 1024px) {
  .vb-hero-grid { grid-template-columns: 7fr 5fr; }
  .vb-grid-5 { grid-template-columns: repeat(5, minmax(0, 1fr)); }
  .vb-grid-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .vb-player-left { flex: 0 0 32%; }
  .vb-player-center { flex: 0 0 38%; }
  .vb-player-right { flex: 0 0 28%; }
  .vb-timeline { display: flex; }
}
@media (min-width: 1200px) {
  .vb-hide-xl { display: inline-flex; }
}
@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { transition-duration: 0.01ms !important; }
}

head.b:template-skin:
body#layout .vb-app-stage,
body#layout .vb-player,
body#layout .vb-yt-dock,
body#layout .vb-drawer,
body#layout .vb-notice { display: none !important; }
body#layout .vb-layout-section {
  border: 1px dashed #9333EA;
  padding: 12px;
  margin: 10px 0;
  border-radius: 8px;
}

