  var PREFS_KEY = "vibebox_blogger_prefs_v1";
  var FAVS_KEY = "vibebox_blogger_favs_v1";
  var PLAYLISTS_KEY = "vibebox_blogger_playlists_v1";

  var DEFAULT_PREFS = {
    playbackMode: "preview-crossfade",
    volume: 0.85,
    muted: false,
    crossfadeSec: 4,
    shuffle: false,
    repeatMode: "all",
    hookStartEnabled: false,
    autoSkipUnavailable: true,
    visStyle: "bars"
  };

  function loadJson(key, fallback) {
    try {
      var raw = window.localStorage.getItem(key);
