  var state = {
    view: isHomepage ? "home" : "blog",
    activeCollection: VB_COLLECTIONS.categories[0],
    prefs: Object.assign({}, DEFAULT_PREFS, loadJson(PREFS_KEY, {})),
    favorites: loadJson(FAVS_KEY, []),
    customPlaylists: loadJson(PLAYLISTS_KEY, []),
    queue: [],
    currentIndex: 0,
    activeCollectionTitle: "Bollywood Party",
    activeSourceLabel: "Authorized 30s Audio · Web Audio Crossfade",
    isPlaying: false,
    isCrossfading: false,
    currentTime: 0,
    duration: 30,
    drawerOpen: false,
    searchQuery: "",
    liveSearchResults: [],
    searchLoading: false,
    unavailable: null
  };

  function getSongsForCollection(kind, id) {
    if (kind === "category") return VB_SONGS.filter(function(s) { return s.categories.indexOf(id) !== -1; });
    if (kind === "mood") return VB_SONGS.filter(function(s) { return s.moods.indexOf(id) !== -1; });
    if (kind === "set") return VB_SONGS.filter(function(s) { return s.sets.indexOf(id) !== -1; });
    return VB_SONGS;
  }

  state.queue = getSongsForCollection("category", "bollywood-party");
  if (state.queue.length === 0) state.queue = VB_SONGS.slice(0, 8);

  // Web Audio Dual-Deck Crossfade Engine + YouTube IFrame Engine
  var Engine = {
    mode: "preview",
    ctx: null,
    audioA: null,
    audioB: null,
    gainA: null,
    gainB: null,
    master: null,
    analyser: null,
    activeDeck: "A",
    fadeTimer: null,
    ytPlayer: null,
    ytReady: false,
    ytLoading: false,
    pendingYt: null,
    pollId: null,

    startPolling: function() {
