      Engine.pollId = window.setInterval(function() { Engine.tick(); }, 250);
    },

    ensurePreviewGraph: function() {
      Engine.startPolling();
      if (Engine.ctx && Engine.audioA && Engine.audioB) {
        if (Engine.ctx.state === "suspended") Engine.ctx.resume();
        return;
      }
      var AC = window.AudioContext || window.webkitAudioContext;
      var ctx = new AC();
      var master = ctx.createGain();
      master.gain.value = state.prefs.muted ? 0 : state.prefs.volume;
      var analyser = ctx.createAnalyser();
      analyser.fftSize = 256;
      analyser.smoothingTimeConstant = 0.8;
      master.connect(analyser);
      analyser.connect(ctx.destination);

      function makeDeck(initGain) {
        var el = new Audio();
        el.crossOrigin = "anonymous";
        el.preload = "auto";
        var src = ctx.createMediaElementSource(el);
        var g = ctx.createGain();
        g.gain.value = initGain;
        src.connect(g);
