      dB.el.addEventListener("ended", function() { Engine.onPreviewEnded("B"); });
      dA.el.addEventListener("error", function() { Engine.onPreviewError("A"); });
      dB.el.addEventListener("error", function() { Engine.onPreviewError("B"); });

      Engine.ctx = ctx;
      Engine.master = master;
      Engine.analyser = analyser;
      Engine.audioA = dA.el;
      Engine.gainA = dA.gain;
      Engine.audioB = dB.el;
      Engine.gainB = dB.gain;
