    fadeOutCurve: function() {
      var arr = new Float32Array(32);
      for (var i = 0; i < 32; i++) arr[i] = Math.cos((i / 31) * Math.PI * 0.5);
      return arr;
    },

    fadeInCurve: function() {
      var arr = new Float32Array(32);
      for (var i = 0; i < 32; i++) arr[i] = Math.sin((i / 31) * Math.PI * 0.5);
      return arr;
    },

    stopYoutube: function() {
