      var dock = document.getElementById("vb-yt-dock");
      if (dock) dock.classList.add("is-hidden");
    },

    stopPreviews: function() {
      if (Engine.fadeTimer) {
        window.clearTimeout(Engine.fadeTimer);
        Engine.fadeTimer = null;
      }
      state.isCrossfading = false;
      if (Engine.audioA) Engine.audioA.pause();
      if (Engine.audioB) Engine.audioB.pause();
    },

    playPreviewImmediate: function(url) {
      Engine.stopYoutube();
      Engine.mode = "preview";
      Engine.ensurePreviewGraph();
      if (Engine.fadeTimer) { window.clearTimeout(Engine.fadeTimer); Engine.fadeTimer = null; }
      state.isCrossfading = false;

      var act = Engine.activeDeck === "A" ? Engine.audioA : Engine.audioB;
      var stb = Engine.activeDeck === "A" ? Engine.audioB : Engine.audioA;
      var actG = Engine.activeDeck === "A" ? Engine.gainA : Engine.gainB;
