      actG.gain.cancelScheduledValues(Engine.ctx.currentTime);
      actG.gain.setValueAtTime(1, Engine.ctx.currentTime);

      act.src = url;
      act.load();
      act.currentTime = 0;
      act.play().then(function() {
        state.isPlaying = true;
        updatePlayerBarUI();
      }).catch(function() {
        state.isPlaying = false;
        updatePlayerBarUI();
      });
    },

    crossfadePreview: function(url) {
      Engine.stopYoutube();
      Engine.mode = "preview";
      Engine.ensurePreviewGraph();
      if (state.isCrossfading) {
        Engine.playPreviewImmediate(url);
        return;
      }
      var act = Engine.activeDeck === "A" ? Engine.audioA : Engine.audioB;
      var stb = Engine.activeDeck === "A" ? Engine.audioB : Engine.audioA;
      var actG = Engine.activeDeck === "A" ? Engine.gainA : Engine.gainB;
      var stbG = Engine.activeDeck === "A" ? Engine.gainB : Engine.gainA;
      var fadeDur = Math.max(0.5, state.prefs.crossfadeSec || 4);

      if (stb.src !== url) { stb.src = url; stb.load(); }
