        updatePlayerBarUI();
        var outDeck = Engine.activeDeck;
        var inDeck = outDeck === "A" ? "B" : "A";
        Engine.fadeTimer = window.setTimeout(function() {
          var oldA = outDeck === "A" ? Engine.audioA : Engine.audioB;
          var oldG = outDeck === "A" ? Engine.gainA : Engine.gainB;
          if (oldA) { oldA.pause(); oldA.currentTime = 0; }
          if (oldG && Engine.ctx) {
            oldG.gain.cancelScheduledValues(Engine.ctx.currentTime);
            oldG.gain.setValueAtTime(0, Engine.ctx.currentTime);
          }
          Engine.activeDeck = inDeck;
          state.isCrossfading = false;
          Engine.fadeTimer = null;
          updatePlayerBarUI();
        }, fadeDur * 1000 + 60);
      }).catch(function() {
        state.isCrossfading = false;
        handleUnavailable("Authorized audio stream could not be started.");
