    },

    ensureYoutube: function(cb) {
      Engine.startPolling();
      if (Engine.ytPlayer && Engine.ytReady) { cb(); return; }
      if (window.YT && window.YT.Player && !Engine.ytPlayer) {
        Engine.ytPlayer = new window.YT.Player("vb-yt-player", {
          width: "100%",
          height: "100%",
          playerVars: { autoplay: 0, controls: 1, modestbranding: 1, rel: 0, playsinline: 1, enablejsapi: 1, origin: window.location.origin },
          events: {
            onReady: function() {
              Engine.ytReady = true;
              Engine.applyVol();
              if (Engine.pendingYt) {
                var p = Engine.pendingYt;
                Engine.pendingYt = null;
                Engine.ytPlayer.loadVideoById(p);
              }
              cb();
            },
            onStateChange: function(e) {
              if (Engine.mode !== "youtube") return;
              if (e.data === 1) { state.isPlaying = true; updatePlayerBarUI(); }
              else if (e.data === 2) { state.isPlaying = false; updatePlayerBarUI(); }
              else if (e.data === 0) {
                if (state.prefs.repeatMode === "one") {
                  Engine.ytPlayer.seekTo(0, true);
                  Engine.ytPlayer.playVideo();
                } else {
                  window.VB.nextSong(true);
                }
              }
