        var s = document.createElement("script");
        s.src = "https://www.youtube.com/iframe_api";
        s.async = true;
        document.head.appendChild(s);
      }
    },

    playYoutube: function(videoId, startSeconds) {
      Engine.stopPreviews();
      Engine.mode = "youtube";
      var dock = document.getElementById("vb-yt-dock");
      if (dock) dock.classList.remove("is-hidden");
      Engine.ensureYoutube(function() {
        if (Engine.ytPlayer && Engine.ytReady) {
          Engine.ytPlayer.loadVideoById({ videoId: videoId, startSeconds: startSeconds || 0 });
          Engine.applyVol();
          state.isPlaying = true;
          updatePlayerBarUI();
        } else {
          Engine.pendingYt = { videoId: videoId, startSeconds: startSeconds || 0 };
