      if (state.prefs.repeatMode === "one") {
        var a = deck === "A" ? Engine.audioA : Engine.audioB;
        if (a) { a.currentTime = 0; a.play(); }
        return;
      }
      window.VB.nextSong(true);
    },

    onPreviewError: function(deck) {
      if (Engine.mode !== "preview" || deck !== Engine.activeDeck) return;
      handleUnavailable("Authorized audio stream failed to load.");
    },

    tick: function() {
      if (Engine.mode === "youtube") {
        if (Engine.ytPlayer && Engine.ytReady) {
          try {
            if (Engine.ytPlayer.getPlayerState() === 1) {
              state.currentTime = Engine.ytPlayer.getCurrentTime() || 0;
              state.duration = Engine.ytPlayer.getDuration() || state.duration;
              updateTimelineOnly();
            }
          } catch (e) {}
        }
        return;
      }
      var audio = Engine.activeDeck === "A" ? Engine.audioA : Engine.audioB;
      if (!audio) return;
      var ct = audio.currentTime || 0;
      var dur = (isFinite(audio.duration) && audio.duration > 0) ? audio.duration : 30;
      if (!audio.paused || ct > 0) {
        state.currentTime = ct;
        state.duration = dur;
        updateTimelineOnly();
      }
      if (!audio.paused && state.prefs.repeatMode !== "one" && !state.isCrossfading &&
          state.prefs.crossfadeSec > 0 && dur > state.prefs.crossfadeSec + 2 &&
          ct >= dur - state.prefs.crossfadeSec) {
        var nxtIdx = computeNextIndex(state.currentIndex, state.queue, state.prefs.shuffle, state.prefs.repeatMode);
        if (nxtIdx !== null && state.queue[nxtIdx] && state.queue[nxtIdx].sources && state.queue[nxtIdx].sources.itunesPreview && state.queue[nxtIdx].sources.itunesPreview.previewUrl) {
          state.currentIndex = nxtIdx;
