  function computeNextIndex(fromIdx, list, shuffle, repeat) {
    if (!list || list.length === 0) return null;
    if (shuffle && list.length > 1) {
      var c = Math.floor(Math.random() * list.length);
      if (c === fromIdx) c = (fromIdx + 1) % list.length;
      return c;
    }
    var n = fromIdx + 1;
    if (n < list.length) return n;
    return repeat === "all" ? 0 : null;
  }

  function handleUnavailable(reason) {
    var song = state.queue[state.currentIndex];
    state.isPlaying = false;
    state.unavailable = song ? { song: song, reason: reason } : null;
    renderNotice();
    updatePlayerBarUI();
    if (state.prefs.autoSkipUnavailable && state.queue.length > 1) {
      window.setTimeout(function() {
        window.VB.nextSong(true);
      }, 1800);
    }
  }

  function startSongInternal(song, modeOverride, useCrossfade) {
    if (!song) return;
    var desired = modeOverride || state.prefs.playbackMode;
    state.unavailable = null;
    state.currentTime = 0;
    renderNotice();

    var yt = song.sources && song.sources.youtube;
    var pv = song.sources && song.sources.itunesPreview;

    if (desired === "preview-crossfade") {
      if (pv && pv.previewUrl) {
        state.duration = 30;
        state.activeSourceLabel = "Authorized Audio · Web Audio Crossfade";
        if (useCrossfade && state.prefs.crossfadeSec > 0) Engine.crossfadePreview(pv.previewUrl);
        else Engine.playPreviewImmediate(pv.previewUrl);
        updatePlayerBarUI();
        renderStage();
        return;
      }
      if (yt && yt.embeddable) {
        state.duration = song.durationSec || 210;
        state.activeSourceLabel = "YouTube Official (" + yt.channelName + ") · No preview";
        Engine.playYoutube(yt.videoId, state.prefs.hookStartEnabled ? (song.hookStartSec || 0) : 0);
        updatePlayerBarUI();
        renderStage();
        return;
      }
    } else {
      if (yt && yt.embeddable) {
        state.duration = song.durationSec || 210;
        state.activeSourceLabel = "YouTube Official · " + yt.channelName;
        Engine.playYoutube(yt.videoId, state.prefs.hookStartEnabled ? (song.hookStartSec || 0) : 0);
        updatePlayerBarUI();
        renderStage();
        return;
      }
      if (pv && pv.previewUrl) {
        state.duration = 30;
        state.activeSourceLabel = "Authorized 30s Audio · Full video unavailable";
        Engine.playPreviewImmediate(pv.previewUrl);
        updatePlayerBarUI();
        renderStage();
        return;
      }
    }
    handleUnavailable("No authorized playback stream is available for this track.");
  }

  function esc(str) {
    return String(str == null ? "" : str)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function fmtTime(sec) {
    if (!isFinite(sec) || sec < 0) return "0:00";
    var m = Math.floor(sec / 60);
    var s = Math.floor(sec % 60);
    return m + ":" + (s < 10 ? "0" : "") + s;
  }

  function artworkInnerHtml(song) {
    var title = song ? song.title : "VB";
    var initials = title.split(/\s+/).filter(Boolean).slice(0, 2).map(function(w) { return w[0].toUpperCase(); }).join("") || "VB";
    if (song && song.artworkUrl) {
      return "<img alt='" + esc(title) + "' referrerpolicy='no-referrer' src='" + esc(song.artworkUrl) + "' onerror='this.style.display=&quot;none&quot;;this.nextSibling.style.display=&quot;flex&quot;;'/><span class='vb-art-fallback' style='display:none;'>" + esc(initials) + "</span>";
    }
    return "<span class='vb-art-fallback' style='display:flex;'>" + esc(initials) + "</span>";
  }

  function artworkHtml(song, sizeClass, isPlaying) {
    var cls = "vb-art " + sizeClass + (isPlaying ? " is-playing" : "");
    return "<div class='" + cls + "'>" + artworkInnerHtml(song) + "</div>";
  }

  function songRowHtml(song, idx, listType) {
    var cur = state.queue[state.currentIndex];
    var isCur = cur && cur.id === song.id;
    var fav = state.favorites.some(function(f) { return f.id === song.id; });
    var pv = song.sources && song.sources.itunesPreview && song.sources.itunesPreview.previewUrl;
    var yt = song.sources && song.sources.youtube && song.sources.youtube.embeddable;
    var playable = Boolean(pv || yt);
    var extUrl = (yt && song.sources.youtube.officialUrl) || (song.sources && song.sources.itunesPreview && song.sources.itunesPreview.officialUrl);
    var prov = pv ? "Authorized 30s Audio" : (yt ? ("YouTube Official · " + song.sources.youtube.channelName) : "Unavailable");
    return "<div class='vb-track-row" + (isCur ? " is-current" : "") + "'>" +
      "<div class='vb-track-left'>" +
        "<span class='vb-mono vb-track-num'>" + (isCur && state.isPlaying ? "&#9654;" : (idx + 1 < 10 ? "0" + (idx + 1) : (idx + 1))) + "</span>" +
        artworkHtml(song, "vb-art-sm", isCur && state.isPlaying) +
        "<div class='vb-track-info'>" +
          "<button class='vb-track-title' type='button' onclick='window.VB.playFromList(&quot;" + esc(listType) + "&quot;," + idx + ")'>" + esc(song.title) + "</button>" +
          "<div class='vb-track-artist'>" + esc(song.artist) + (song.album ? " &#183; " + esc(song.album) : "") + (song.releaseYear ? " (" + song.releaseYear + ")" : "") + "</div>" +
          "<div class='vb-track-meta'><span>" + esc(song.language || "Music") + "</span><span>&#183;</span><span>" + esc(song.genre || "Audio") + "</span><span>&#183;</span><span>" + esc(prov) + "</span></div>" +
        "</div>" +
      "</div>" +
      "<div class='vb-track-right'>" +
        (extUrl ? "<a class='vb-official-link' href='" + esc(extUrl) + "' target='_blank' rel='noopener noreferrer'>Official &#8599;</a>" : "") +
        "<span class='vb-mono' style='font-size:0.75rem;color:#94A3B8;'>" + fmtTime(song.durationSec || 30) + "</span>" +
        "<button type='button' aria-label='Favorite' onclick='window.VB.toggleFavoriteById(&quot;" + esc(song.id) + "&quot;,&quot;" + esc(listType) + "&quot;)' style='color:" + (fav ? "#EC4899" : "#94A3B8") + ";font-size:1rem;'>" + (fav ? "&#9829;" : "&#9825;") + "</button>" +
        (playable ? "<button class='vb-track-play-btn' type='button' onclick='window.VB.playFromList(&quot;" + esc(listType) + "&quot;," + idx + ")'>" + (isCur && state.isPlaying ? "Playing" : "Play") + "</button>" : "<span style='font-size:0.75rem;color:#FBBF24;'>Unavailable</span>") +
      "</div>" +
    "</div>";
  }

  function collectionCardHtml(col, kind) {
    var list = getSongsForCollection(kind, col.id);
    var active = state.activeCollectionTitle === col.title && state.isPlaying;
    return "<div class='vb-card vb-card-row" + (active ? " is-active" : "") + "'>" +
      "<div style='display:flex;align-items:center;gap:0.875rem;min-width:0;flex:1;cursor:pointer;' onclick='window.VB.openCollection(&quot;" + esc(kind) + "&quot;,&quot;" + esc(col.id) + "&quot;)'>" +
        artworkHtml(list[0] || { title: col.title }, "vb-art-md", active) +
        "<div style='min-width:0;'>" +
          "<div class='vb-card-title' style='white-space:nowrap;overflow:hidden;text-overflow:ellipsis;'>" + esc(col.title) + "</div>" +
          "<div class='vb-card-sub'>" + esc(col.subtitle) + "</div>" +
          "<div class='vb-mono vb-card-meta'>" + list.length + " real songs</div>" +
        "</div>" +
      "</div>" +
      "<button class='vb-play-circle' type='button' aria-label='Play " + esc(col.title) + "' onclick='window.VB.playCollection(&quot;" + esc(kind) + "&quot;,&quot;" + esc(col.id) + "&quot;)'>&#9654;</button>" +
    "</div>";
  }

  // Live HTML5 Canvas Visualizer
  var visRaf = 0;
  var visPhase = 0;
  function startVisualizerLoop() {
    if (visRaf) window.cancelAnimationFrame(visRaf);
    var freqData = new Uint8Array(128);
    var timeData = new Uint8Array(128);

    function draw() {
      var canvas = document.getElementById("vb-vis-canvas");
      if (canvas) {
        var ctx = canvas.getContext("2d");
        var w = canvas.width;
        var h = canvas.height;
        visPhase += state.isPlaying ? 0.045 : 0.01;
        ctx.clearRect(0, 0, w, h);

        if (Engine.mode === "preview" && Engine.analyser && state.isPlaying) {
          Engine.analyser.getByteFrequencyData(freqData);
          Engine.analyser.getByteTimeDomainData(timeData);
        } else {
          var amp = state.isPlaying ? 58 : 16;
          var base = state.isPlaying ? 72 : 22;
          for (var i = 0; i < 128; i++) {
            var wv = Math.sin(visPhase + i * 0.25) * 0.6 + Math.cos(visPhase * 1.3 - i * 0.17) * 0.4;
            freqData[i] = Math.max(8, Math.min(255, Math.round(base + wv * amp)));
            timeData[i] = Math.round(128 + Math.sin(visPhase * 1.6 + i * 0.21) * (state.isPlaying ? 32 : 10));
          }
        }

        var style = state.prefs.visStyle || "bars";
        var bass = 0;
        for (var b = 0; b < 8; b++) bass += freqData[b];
        var bassNorm = bass / (8 * 255);

        if (style === "gradient") {
          var g1 = ctx.createRadialGradient(w * (0.3 + Math.sin(visPhase * 0.7) * 0.14), h * 0.45, 10, w * 0.3, h * 0.45, Math.max(80, w * (0.32 + bassNorm * 0.22)));
          g1.addColorStop(0, "rgba(168,85,247,0.5)");
          g1.addColorStop(1, "rgba(168,85,247,0)");
          ctx.fillStyle = g1;
          ctx.fillRect(0, 0, w, h);
          var g2 = ctx.createRadialGradient(w * (0.72 + Math.cos(visPhase * 0.5) * 0.12), h * 0.55, 10, w * 0.72, h * 0.55, Math.max(80, w * (0.3 + bassNorm * 0.2)));
          g2.addColorStop(0, "rgba(56,189,248,0.45)");
          g2.addColorStop(1, "rgba(37,99,235,0)");
          ctx.fillStyle = g2;
          ctx.fillRect(0, 0, w, h);
          ctx.beginPath();
          for (var t = 0; t < 128; t++) {
            var tx = (t / 127) * w;
            var ty = h * 0.5 + ((timeData[t] - 128) / 128) * (h * 0.34);
            if (t === 0) ctx.moveTo(tx, ty); else ctx.lineTo(tx, ty);
          }
          ctx.strokeStyle = "rgba(248,250,252,0.85)";
          ctx.lineWidth = 2.5;
          ctx.stroke();
        } else if (style === "circular") {
          var cx = w / 2, cy = h / 2, r = Math.min(w, h) * (0.24 + bassNorm * 0.05);
          for (var p = 0; p < 64; p++) {
            var ang = (p / 64) * Math.PI * 2 + visPhase * 0.3;
            var ampP = (freqData[p] / 255) * (Math.min(w, h) * 0.22);
            ctx.beginPath();
            ctx.moveTo(cx + Math.cos(ang) * r, cy + Math.sin(ang) * r);
            ctx.lineTo(cx + Math.cos(ang) * (r + Math.max(4, ampP)), cy + Math.sin(ang) * (r + Math.max(4, ampP)));
            ctx.strokeStyle = p % 2 === 0 ? "#A855F7" : "#38BDF8";
            ctx.lineWidth = 3;
            ctx.lineCap = "round";
            ctx.stroke();
          }
        } else if (style === "spectrum") {
          var sg = ctx.createLinearGradient(0, 0, w, 0);
          sg.addColorStop(0, "#9333EA"); sg.addColorStop(0.5, "#6366F1"); sg.addColorStop(1, "#38BDF8");
          var fg = ctx.createLinearGradient(0, 0, 0, h);
          fg.addColorStop(0, "rgba(168,85,247,0.45)"); fg.addColorStop(1, "rgba(37,99,235,0.02)");
          ctx.beginPath();
          ctx.moveTo(0, h);
          for (var k = 0; k < 48; k++) {
            ctx.lineTo((k / 47) * w, h - Math.max(8, (freqData[k] / 255) * (h - 24)));
          }
          ctx.lineTo(w, h);
          ctx.closePath();
          ctx.fillStyle = fg;
          ctx.fill();
          ctx.beginPath();
          for (var k2 = 0; k2 < 48; k2++) {
            var sx = (k2 / 47) * w, sy = h - Math.max(8, (freqData[k2] / 255) * (h - 24));
            if (k2 === 0) ctx.moveTo(sx, sy); else ctx.lineTo(sx, sy);
          }
          ctx.strokeStyle = sg;
          ctx.lineWidth = 3;
          ctx.stroke();
        } else {
          var bars = 42, gap = 5, bw = (w - gap * (bars - 1)) / bars;
          var bg = ctx.createLinearGradient(0, h, 0, 0);
          bg.addColorStop(0, "#2563EB"); bg.addColorStop(0.6, "#9333EA"); bg.addColorStop(1, "#38BDF8");
          ctx.fillStyle = bg;
          for (var j = 0; j < bars; j++) {
            var bh = Math.max(6, (freqData[j] / 255) * (h - 18));
            ctx.fillRect(j * (bw + gap), h - bh, bw, bh);
          }
        }
      }
      visRaf = window.requestAnimationFrame(draw);
    }
    visRaf = window.requestAnimationFrame(draw);
  }

  function renderStage() {
    var mount = document.getElementById("vb-app-stage");
    if (!mount) return;
    var blogWrap = document.getElementById("vb-blog-wrap");
    if (blogWrap) {
      blogWrap.style.display = (state.view === "home" || state.view === "blog") ? "block" : "none";
    }

    var btns = document.querySelectorAll("[data-vb-nav]");
    for (var i = 0; i < btns.length; i++) {
      var b = btns[i];
      b.classList.toggle("is-active", b.getAttribute("data-vb-nav") === state.view);
    }

    if (state.view === "blog") {
      mount.innerHTML = "";
      return;
    }

    var cur = state.queue[state.currentIndex] || VB_SONGS[0];

    if (state.view === "discover") {
      var groups = ["Hindi", "Punjabi", "English", "Regional"];
      var gHtml = groups.map(function(g) {
        var cats = VB_COLLECTIONS.categories.filter(function(c) { return c.group === g; });
        return "<div class='vb-section'><h2 style='font-size:1.35rem;'>" + esc(g) + "</h2><div class='vb-grid-3'>" +
          cats.map(function(c) { return collectionCardHtml(c, "category"); }).join("") +
          "</div></div>";
      }).join("");
      mount.innerHTML = "<h1 class='vb-hero-title'>Discover 22 Real-Song Categories</h1><p class='vb-hero-sub'>Curated Hindi, Punjabi, English, and Regional stations ready for Auto-DJ playback.</p>" + gHtml;
      return;
    }

    if (state.view === "party") {
      var setsHtml = VB_COLLECTIONS.sets.map(function(s) {
        return collectionCardHtml(s, "set");
      }).join("");
      mount.innerHTML = "<h1 class='vb-hero-title'>10 Ready-Made Party Sets</h1><p class='vb-hero-sub'>Launch House Party, Bollywood Night, Punjabi Night, Wedding Dance, and more in one click.</p><div class='vb-grid-3' style='margin-top:1.5rem;'>" + setsHtml + "</div>" +
        "<div class='vb-section'><div class='vb-section-head'><h2>Active Queue &#183; " + esc(state.activeCollectionTitle) + "</h2></div><div class='vb-tracklist'>" +
        state.queue.map(function(s, idx) { return songRowHtml(s, idx, "queue"); }).join("") + "</div></div>";
      return;
    }

    if (state.view === "mood") {
      mount.innerHTML = "<h1 class='vb-hero-title'>8 Mood Radio Stations</h1><p class='vb-hero-sub'>Select a mood to stream matching real songs continuously.</p><div class='vb-grid-3' style='margin-top:1.5rem;'>" +
        VB_COLLECTIONS.moods.map(function(m) { return collectionCardHtml(m, "mood"); }).join("") + "</div>";
      return;
    }

    if (state.view === "collection" && state.activeCollection) {
      var col = state.activeCollection;
      var list = getSongsForCollection(col.kind, col.id);
      window._vbViewingList = list;
      mount.innerHTML = "<div style='margin-bottom:1rem;font-size:0.8rem;color:#94A3B8;'><button type='button' onclick='window.VB.go(&quot;home&quot;)' style='color:#38BDF8;'>Home</button> &#47; <span>" + esc(col.title) + "</span></div>" +
        "<section class='vb-hero'><div class='vb-hero-left'>" + artworkHtml(list[0] || { title: col.title }, "vb-art-xl", state.activeCollectionTitle === col.title && state.isPlaying) +
        "<div><p class='vb-kicker'>" + esc(col.kind.toUpperCase()) + " &#183; " + list.length + " REAL SONGS</p><h1 class='vb-hero-title'>" + esc(col.title) + "</h1><p class='vb-hero-sub'>" + esc(col.subtitle) + "</p>" +
        "<div class='vb-btn-row'><button class='vb-btn-primary' type='button' onclick='window.VB.playCollection(&quot;" + esc(col.kind) + "&quot;,&quot;" + esc(col.id) + "&quot;)'>&#9654; Play Mix</button>" +
        "<button class='vb-btn-sec' type='button' onclick='window.VB.toggleShuffle();window.VB.playCollection(&quot;" + esc(col.kind) + "&quot;,&quot;" + esc(col.id) + "&quot;)'>&#8646; Shuffle</button></div></div></div></section>" +
        "<div class='vb-tracklist'>" + list.map(function(s, idx) { return songRowHtml(s, idx, "viewing"); }).join("") + "</div>";
      return;
    }

    if (state.view === "search") {
      var q = state.searchQuery.trim().toLowerCase();
      var curated = q ? VB_SONGS.filter(function(s) {
        return s.title.toLowerCase().indexOf(q) !== -1 || s.artist.toLowerCase().indexOf(q) !== -1 || (s.album && s.album.toLowerCase().indexOf(q) !== -1) || s.genre.toLowerCase().indexOf(q) !== -1 || s.language.toLowerCase().indexOf(q) !== -1;
      }) : VB_SONGS.slice(0, 10);
      window._vbSearchCurated = curated;
      window._vbSearchLive = state.liveSearchResults;
      mount.innerHTML = "<h1 class='vb-hero-title'>Search Real Songs &amp; Artists</h1><p class='vb-hero-sub'>Search curated tracks plus live iTunes 30-second official audio streams directly inside Blogger.</p>" +
        "<div class='vb-input-box' style='margin-top:1.25rem;'><input id='vb-search-inp' type='search' value='" + esc(state.searchQuery) + "' placeholder='Search Kesariya, Arijit, Diljit, Eminem, Garba, Tamil...' oninput='window.VB.onSearchInput(this.value)'/></div>" +
        "<div class='vb-section'><div class='vb-section-head'><h2>Catalog Matches (" + curated.length + ")</h2></div><div class='vb-tracklist'>" +
        (curated.length ? curated.map(function(s, idx) { return songRowHtml(s, idx, "searchCurated"); }).join("") : "<p style='padding:1rem;color:#94A3B8;'>No catalog matches.</p>") + "</div></div>" +
        (q ? "<div class='vb-section'><div class='vb-section-head'><h2>Live Official iTunes Results (" + state.liveSearchResults.length + ")" + (state.searchLoading ? " &#183; Searching..." : "") + "</h2></div><div class='vb-tracklist'>" +
        (state.liveSearchResults.length ? state.liveSearchResults.map(function(s, idx) { return songRowHtml(s, idx, "searchLive"); }).join("") : "<p style='padding:1rem;color:#94A3B8;'>" + (state.searchLoading ? "Loading live official audio previews..." : "No live results found.") + "</p>") + "</div></div>" : "");
      var inp = document.getElementById("vb-search-inp");
      if (inp) { inp.focus(); try { inp.setSelectionRange(inp.value.length, inp.value.length); } catch (e) {} }
      return;
    }

    if (state.view === "saved") {
      window._vbFavList = state.favorites;
      var plsHtml = state.customPlaylists.length ? "<div class='vb-grid-3' style='margin-top:1rem;'>" + state.customPlaylists.map(function(pl) {
        return "<div class='vb-card vb-card-row'><div><div class='vb-card-title'>" + esc(pl.name) + "</div><div class='vb-card-meta'>" + pl.songs.length + " songs</div></div>" +
          "<div style='display:flex;gap:0.5rem;'><button class='vb-play-circle' type='button' onclick='window.VB.playSavedPlaylist(&quot;" + esc(pl.id) + "&quot;)'>&#9654;</button>" +
          "<button class='vb-btn-sec' type='button' style='padding:0.4rem 0.65rem;font-size:0.75rem;' onclick='window.VB.deleteSavedPlaylist(&quot;" + esc(pl.id) + "&quot;)'>Delete</button></div></div>";
      }).join("") + "</div>" : "<p style='margin-top:0.75rem;color:#94A3B8;'>No custom playlists saved yet. Save your active queue below or in the Queue drawer.</p>";

      mount.innerHTML = "<h1 class='vb-hero-title'>Saved Playlists &amp; Favorites</h1><p class='vb-hero-sub'>Stored directly in your browser LocalStorage &#8212; zero login required.</p>" +
        "<form style='margin-top:1.25rem;display:flex;flex-wrap:wrap;gap:0.75rem;' onsubmit='window.VB.saveQueueFromInput(event)'>" +
          "<input class='vb-text-input' id='vb-save-name' style='flex:1;min-width:220px;' placeholder='Save current queue (&quot;" + esc(state.activeCollectionTitle) + "&quot;) as playlist...'/>" +
          "<button class='vb-btn-primary' type='submit'>Save Active Queue</button>" +
        "</form>" +
        "<div class='vb-section'><h2>Custom Playlists (" + state.customPlaylists.length + ")</h2>" + plsHtml + "</div>" +
        "<div class='vb-section'><h2>Favorite Songs (" + state.favorites.length + ")</h2><div class='vb-tracklist'>" +
        (state.favorites.length ? state.favorites.map(function(s, idx) { return songRowHtml(s, idx, "favorites"); }).join("") : "<p style='padding:1rem;color:#94A3B8;'>Tap the heart icon on any song to save it here.</p>") +
        "</div></div>";
      return;
    }

    // DEFAULT HOME VIEW
    var extUrl = cur && ((cur.sources && cur.sources.youtube && cur.sources.youtube.officialUrl) || (cur.sources && cur.sources.itunesPreview && cur.sources.itunesPreview.officialUrl));
    var visNote = Engine.mode === "preview" && state.isPlaying ? "Live Web Audio FFT Spectrum" : (state.prefs.playbackMode === "youtube" ? "Ambient Motion &#183; Official video plays in dock" : "Press Play for live Web Audio spectrum");

    mount.innerHTML =
      "<section class='vb-hero'>" +
        "<div class='vb-glow-1'></div><div class='vb-glow-2'></div>" +
        "<div class='vb-hero-grid'>" +
          "<div class='vb-hero-left'>" +
            artworkHtml(cur, "vb-art-xl", state.isPlaying) +
            "<div style='min-width:0;flex:1;'>" +
              "<p class='vb-kicker'>" + esc(state.activeCollectionTitle) + " &#183; " + esc(state.activeSourceLabel) + "</p>" +
              "<h1 class='vb-hero-title'>Press Play. Let the Music Flow.</h1>" +
              "<p class='vb-hero-sub'><strong style='color:#FFFFFF;'>" + esc(cur.title) + "</strong> by " + esc(cur.artist) + (cur.album ? " &#183; " + esc(cur.album) : "") + (cur.releaseYear ? " (" + cur.releaseYear + ")" : "") + (state.isCrossfading ? " &#183; Crossfading" : "") + "</p>" +
              (extUrl ? "<a class='vb-official-link' href='" + esc(extUrl) + "' target='_blank' rel='noopener noreferrer'>Open Official Song Source &#8599;</a>" : "") +
              "<div class='vb-btn-row'>" +
                "<button class='vb-btn-primary' type='button' onclick='window.VB.togglePlayPause()'>" + (state.isPlaying ? "&#10074;&#10074; Pause Flow" : "&#9654; Press Play") + "</button>" +
                "<button class='vb-btn-sec' type='button' onclick='window.VB.nextSong()'>&#9197; Next Song</button>" +
                "<button class='vb-btn-sec" + (state.prefs.shuffle ? " is-on" : "") + "' type='button' onclick='window.VB.toggleShuffle()'>&#8646; " + (state.prefs.shuffle ? "Shuffle On" : "Shuffle") + "</button>" +
                "<button class='vb-btn-sec' type='button' onclick='window.VB.go(&quot;party&quot;)'>10 Party Sets</button>" +
              "</div>" +
              "<div class='vb-engine-switch'><span>Playback Engine:</span>" +
                "<button class='" + (state.prefs.playbackMode === "preview-crossfade" ? "is-active" : "") + "' type='button' onclick='window.VB.setPlaybackMode(&quot;preview-crossfade&quot;)'>Web Audio Crossfade (30s Official)</button>" +
                "<span>&#183;</span>" +
                "<button class='" + (state.prefs.playbackMode === "youtube" ? "is-active" : "") + "' type='button' onclick='window.VB.setPlaybackMode(&quot;youtube&quot;)'>Full Song (YouTube Official)</button>" +
              "</div>" +
            "</div>" +
          "</div>" +
          "<div>" +
            "<div class='vb-vis-box'><canvas class='vb-vis-canvas' height='240' id='vb-vis-canvas' width='860'></canvas><div class='vb-vis-caption'>" + visNote + "</div></div>" +
            "<div class='vb-vis-modes'>" +
              [["bars","Frequency Bars"],["circular","Circular Wave"],["spectrum","Neon Spectrum"],["gradient","Ambient Glow"]].map(function(m) {
                return "<button class='vb-vis-mode-btn" + (state.prefs.visStyle === m[0] ? " is-active" : "") + "' type='button' onclick='window.VB.setVisStyle(&quot;" + m[0] + "&quot;)'>" + m[1] + "</button>";
              }).join("") +
            "</div>" +
          "</div>" +
        "</div>" +
      "</section>" +

      "<section class='vb-section'><div class='vb-section-head'><div><h2>Ready-Made Party Sets</h2><p>One-click multi-genre party queues ready to flow.</p></div><button class='vb-link-more' type='button' onclick='window.VB.go(&quot;party&quot;)'>All 10 Sets &#8594;</button></div><div class='vb-grid-5'>" +
        VB_COLLECTIONS.sets.slice(0, 5).map(function(s) {
          var list = getSongsForCollection("set", s.id);
          var active = state.activeCollectionTitle === s.title && state.isPlaying;
          return "<div class='vb-card" + (active ? " is-active" : "") + "'><div style='display:flex;align-items:center;justify-content:space-between;gap:0.5rem;'>" + artworkHtml(list[0] || { title: s.title }, "vb-art-sm", active) +
            "<button class='vb-play-circle' type='button' onclick='window.VB.playCollection(&quot;set&quot;,&quot;" + esc(s.id) + "&quot;)'>&#9654;</button></div>" +
            "<div style='margin-top:0.75rem;cursor:pointer;' onclick='window.VB.openCollection(&quot;set&quot;,&quot;" + esc(s.id) + "&quot;)'><div class='vb-card-title'>" + esc(s.title) + "</div><div class='vb-card-sub'>" + esc(s.subtitle) + "</div></div>" +
            "<div class='vb-mono vb-card-meta'>" + list.length + " real songs</div></div>";
        }).join("") +
      "</div></section>" +

      "<section class='vb-section'><div class='vb-section-head'><div><h2>Mood Radio</h2><p>8 continuous radio stations matched to your mood.</p></div><button class='vb-link-more' type='button' onclick='window.VB.go(&quot;mood&quot;)'>All 8 Radios &#8594;</button></div><div class='vb-grid-4'>" +
        VB_COLLECTIONS.moods.map(function(m) {
          var active = state.activeCollectionTitle === m.title && state.isPlaying;
          return "<div class='vb-card" + (active ? " is-active" : "") + "' style='background:linear-gradient(135deg," + esc(m.accentFrom) + "24," + esc(m.accentTo) + "16);'>" +
            "<div style='display:flex;align-items:flex-start;justify-content:space-between;gap:0.5rem;'><div style='cursor:pointer;min-width:0;' onclick='window.VB.openCollection(&quot;mood&quot;,&quot;" + esc(m.id) + "&quot;)'><div class='vb-card-title'>" + esc(m.title) + "</div><div class='vb-card-sub'>" + esc(m.subtitle) + "</div></div>" +
            "<button class='vb-play-circle' type='button' onclick='window.VB.playCollection(&quot;mood&quot;,&quot;" + esc(m.id) + "&quot;)'>&#9654;</button></div></div>";
        }).join("") +
      "</div></section>" +

      "<section class='vb-section'><div class='vb-section-head'><div><h2>Discover Categories</h2><p>22 stations across Hindi, Punjabi, English &amp; Regional hits.</p></div><button class='vb-link-more' type='button' onclick='window.VB.go(&quot;discover&quot;)'>View All 22 &#8594;</button></div><div class='vb-grid-3'>" +
        VB_COLLECTIONS.categories.slice(0, 6).map(function(c) { return collectionCardHtml(c, "category"); }).join("") +
      "</div></section>";
  }

  function updateTimelineOnly() {
    var ct = document.getElementById("vb-bar-ct");
    var dur = document.getElementById("vb-bar-dur");
    var seek = document.getElementById("vb-bar-seek");
    var safeDur = state.duration > 0 ? state.duration : 30;
    if (ct) ct.textContent = fmtTime(state.currentTime);
    if (dur) dur.textContent = fmtTime(safeDur);
    if (seek) { seek.max = safeDur; seek.value = Math.min(state.currentTime, safeDur); }
  }

  function updatePlayerBarUI() {
    var cur = state.queue[state.currentIndex];
    if (!cur) return;
    var art = document.getElementById("vb-bar-art");
    if (art) {
      art.className = "vb-art vb-art-sm" + (state.isPlaying ? " is-playing" : "");
      art.innerHTML = artworkInnerHtml(cur);
    }
    var titleEl = document.getElementById("vb-bar-title");
    var metaEl = document.getElementById("vb-bar-meta");
    var srcEl = document.getElementById("vb-bar-source");
    var playEl = document.getElementById("vb-bar-play");
    var favEl = document.getElementById("vb-bar-fav");
    var shufEl = document.getElementById("vb-bar-shuffle");
    var repEl = document.getElementById("vb-bar-repeat");
    var modeEl = document.getElementById("vb-bar-mode");
    var ytCh = document.getElementById("vb-yt-channel");
    var ytExt = document.getElementById("vb-yt-ext");

    if (titleEl) titleEl.textContent = cur.title + (state.isCrossfading ? " · Crossfading" : "");
    if (metaEl) metaEl.textContent = cur.artist + (cur.album ? " · " + cur.album : "");
    if (srcEl) {
      var ext = (cur.sources && cur.sources.itunesPreview && cur.sources.itunesPreview.officialUrl) || (cur.sources && cur.sources.youtube && cur.sources.youtube.officialUrl);
      srcEl.innerHTML = "<span>" + esc(state.activeSourceLabel) + "</span>" + (ext ? "<a href='" + esc(ext) + "' target='_blank' rel='noopener noreferrer' style='color:#38BDF8;'>Official &#8599;</a>" : "");
    }
    if (playEl) playEl.innerHTML = state.isPlaying ? "&#10074;&#10074;" : "&#9654;";
    if (favEl) {
      var isFav = state.favorites.some(function(f) { return f.id === cur.id; });
      favEl.innerHTML = isFav ? "&#9829;" : "&#9825;";
      favEl.style.color = isFav ? "#EC4899" : "#94A3B8";
    }
    if (shufEl) shufEl.style.color = state.prefs.shuffle ? "#38BDF8" : "#94A3B8";
    if (repEl) {
      repEl.style.color = state.prefs.repeatMode !== "off" ? "#C084FC" : "#94A3B8";
      repEl.innerHTML = state.prefs.repeatMode === "one" ? "&#8635;1" : "&#8635;";
    }
    if (modeEl) {
      modeEl.textContent = state.prefs.playbackMode === "preview-crossfade" ? ("Fade " + state.prefs.crossfadeSec + "s") : "Full Song";
    }
    if (ytCh && cur.sources && cur.sources.youtube) ytCh.textContent = cur.sources.youtube.channelName || "YouTube Official";
    if (ytExt && cur.sources && cur.sources.youtube) ytExt.href = cur.sources.youtube.officialUrl || "#";

    updateTimelineOnly();
    if (state.drawerOpen) renderDrawer();
  }

  function renderNotice() {
    var el = document.getElementById("vb-notice");
    if (!el) return;
    if (!state.unavailable) { el.classList.remove("is-open"); el.innerHTML = ""; return; }
    var s = state.unavailable.song;
    var ext = (s.sources && s.sources.youtube && s.sources.youtube.officialUrl) || (s.sources && s.sources.itunesPreview && s.sources.itunesPreview.officialUrl);
    el.classList.add("is-open");
    el.innerHTML = "<div style='display:flex;justify-content:space-between;gap:0.75rem;'><div><strong>" + esc(s.title) + " &#8212; Unavailable</strong><p style='margin:0.3rem 0 0;color:#CBD5E1;'>" + esc(state.unavailable.reason) + "</p>" +
      "<div style='margin-top:0.6rem;display:flex;gap:0.75rem;'>" + (ext ? "<a href='" + esc(ext) + "' target='_blank' rel='noopener noreferrer' style='color:#38BDF8;font-weight:600;'>Official Link &#8599;</a>" : "") +
      "<button type='button' onclick='window.VB.nextSong()' style='color:#E2E8F0;font-weight:600;'>Skip Track &#8594;</button></div></div>" +
      "<button type='button' onclick='window.VB.dismissNotice()' style='color:#94A3B8;'>&#10005;</button></div>";
  }

  function renderDrawer() {
    var el = document.getElementById("vb-drawer");
    if (!el) return;
    if (!state.drawerOpen) { el.classList.remove("is-open"); return; }
    el.classList.add("is-open");
    var upNext = state.queue.slice(state.currentIndex + 1).concat(state.prefs.repeatMode === "all" ? state.queue.slice(0, state.currentIndex) : []);
    var isPv = state.prefs.playbackMode === "preview-crossfade";
    el.innerHTML =
      "<div style='display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(255,255,255,0.1);padding-bottom:0.75rem;'>" +
        "<div><div style='font-size:0.75rem;color:#C084FC;'>" + esc(state.activeCollectionTitle) + " &#183; Track " + (state.currentIndex + 1) + " of " + state.queue.length + "</div>" +
        "<h2 class='vb-display' style='font-size:1.15rem;'>Auto-DJ Queue &amp; Crossfade Controls</h2></div>" +
        "<button type='button' onclick='window.VB.toggleDrawer()' style='padding:0.35rem 0.55rem;border:1px solid rgba(255,255,255,0.15);border-radius:0.5rem;'>&#10005;</button>" +
      "</div>" +
      "<div style='margin-top:1rem;display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;padding:0.9rem;border-radius:0.75rem;border:1px solid rgba(255,255,255,0.1);background:rgba(255,255,255,0.03);'>" +
        "<div><div style='font-size:0.75rem;font-weight:600;'>Playback Source</div>" +
        "<div style='margin-top:0.5rem;display:flex;gap:0.5rem;'>" +
          "<button type='button' class='vb-btn-sec" + (isPv ? " is-on" : "") + "' style='flex:1;padding:0.45rem;font-size:0.72rem;justify-content:center;' onclick='window.VB.setPlaybackMode(&quot;preview-crossfade&quot;)'>30s Web Audio Crossfade</button>" +
          "<button type='button' class='vb-btn-sec" + (!isPv ? " is-on" : "") + "' style='flex:1;padding:0.45rem;font-size:0.72rem;justify-content:center;' onclick='window.VB.setPlaybackMode(&quot;youtube&quot;)'>Full Song (YouTube)</button>" +
        "</div><p style='margin:0.45rem 0 0;font-size:0.7rem;color:#94A3B8;'>" + (isPv ? "Dual-deck Web Audio gain curves active on authorized CORS audio." : "YouTube IFrame plays full official songs; crossfade applies to Web Audio streams only.") + "</p></div>" +
        "<div><div style='display:flex;justify-content:space-between;font-size:0.75rem;'><span>Crossfade Duration</span><span class='vb-mono' style='color:#38BDF8;'>" + (isPv ? state.prefs.crossfadeSec + "s" : "Web Audio Mode") + "</span></div>" +
        "<input class='vb-slider' type='range' min='0' max='10' step='1' " + (!isPv ? "disabled='disabled'" : "") + " value='" + state.prefs.crossfadeSec + "' oninput='window.VB.setCrossfade(Number(this.value))' style='width:100%;margin-top:0.55rem;'/>" +
        "<div style='margin-top:0.6rem;display:flex;gap:1rem;font-size:0.72rem;color:#CBD5E1;'>" +
          "<label><input type='checkbox' " + (state.prefs.hookStartEnabled ? "checked='checked'" : "") + " onchange='window.VB.toggleHookStart()'/> Start from Hook</label>" +
          "<label><input type='checkbox' " + (state.prefs.autoSkipUnavailable ? "checked='checked'" : "") + " onchange='window.VB.toggleAutoSkip()'/> Auto-skip unavailable</label>" +
        "</div></div>" +
      "</div>" +
      "<form style='margin-top:0.9rem;display:flex;gap:0.5rem;' onsubmit='window.VB.addCustomAudioUrl(event)'>" +
        "<input class='vb-text-input' id='vb-custom-title' style='width:9rem;' placeholder='Track title'/>" +
        "<input class='vb-text-input' id='vb-custom-url' type='url' style='flex:1;' placeholder='https://... authorized CORS MP3/M4A/WAV URL'/>" +
        "<button class='vb-btn-sec' type='submit' style='padding:0.45rem 0.85rem;font-size:0.75rem;background:#2563EB;border-color:#2563EB;'>+ Add Audio</button>" +
      "</form>" +
      "<div style='margin-top:1rem;font-size:0.75rem;font-weight:600;color:#94A3B8;'>Up Next (" + upNext.length + ")</div>" +
      "<div class='vb-tracklist' style='margin-top:0.5rem;'>" + upNext.slice(0, 15).map(function(s, i) {
        return "<div class='vb-track-row' style='padding:0.55rem 0.75rem;cursor:pointer;' onclick='window.VB.playFromQueueId(&quot;" + esc(s.id) + "&quot;)'>" +
          "<div class='vb-track-left'><span class='vb-mono vb-track-num'>" + (i + 1) + "</span>" + artworkHtml(s, "vb-art-sm", false) +
          "<div class='vb-track-info'><div class='vb-track-title'>" + esc(s.title) + "</div><div class='vb-track-artist'>" + esc(s.artist) + "</div></div></div>" +
          "<span class='vb-mono' style='font-size:0.7rem;color:#94A3B8;'>" + fmtTime(s.durationSec || 30) + "</span></div>";
      }).join("") + "</div>";
  }

  var searchTimer = null;
  window._vbJsonpSearch = function(data) {
    state.searchLoading = false;
    var results = (data && data.results) || [];
    state.liveSearchResults = results.filter(function(r) { return r.previewUrl && r.trackName; }).map(function(r) {
      return {
        id: "itunes-" + r.trackId,
        title: r.trackName,
        artist: r.artistName || "Artist",
        album: r.collectionName || "Single",
        releaseYear: r.releaseDate ? Number(r.releaseDate.slice(0, 4)) : null,
        genre: r.primaryGenreName || "Music",
        language: "Global",
        moods: [], categories: [], sets: [],
        artworkUrl: (r.artworkUrl100 || "").replace("100x100bb", "600x600bb"),
        durationSec: Math.round((r.trackTimeMillis || 30000) / 1000),
        sources: { itunesPreview: { previewUrl: r.previewUrl, officialUrl: r.trackViewUrl || "#" } }
      };
    });
    if (state.view === "search") renderStage();
  };

  function enhanceBlogPostAudio() {
    var audios = document.querySelectorAll(".vb-post-body audio, .vb-post-body [data-vibebox-url]");
    for (var i = 0; i < audios.length; i++) {
      (function(node) {
        var src = node.getAttribute("data-vibebox-url") || node.getAttribute("src") || (node.querySelector("source") && node.querySelector("source").getAttribute("src"));
        if (!src || node.getAttribute("data-vb-enhanced")) return;
        node.setAttribute("data-vb-enhanced", "1");
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = "vb-btn-primary";
        btn.style.marginTop = "0.5rem";
        btn.textContent = "Play in VIBEBOX Auto-DJ";
        btn.onclick = function() {
          var track = {
            id: "post-" + Date.now(),
            title: node.getAttribute("data-vibebox-title") || document.title || "Blog Audio Track",
            artist: node.getAttribute("data-vibebox-artist") || "Featured Blog Mix",
            album: "Blog Feature",
            releaseYear: new Date().getFullYear(),
            genre: "Blog Audio",
            language: "Global",
            moods: [], categories: [], sets: [],
            artworkUrl: node.getAttribute("data-vibebox-artwork") || "",
            durationSec: 180,
            sources: { itunesPreview: { previewUrl: src, officialUrl: window.location.href } }
          };
          state.queue = [track].concat(state.queue);
          state.currentIndex = 0;
          state.activeCollectionTitle = "Blog Post Mix";
          startSongInternal(track, "preview-crossfade", false);
        };
        node.parentNode.insertBefore(btn, node.nextSibling);
      })(audios[i]);
    }
  }

  window.VB = {
    go: function(view) {
      state.view = view;
      renderStage();
      window.scrollTo({ top: 0, behavior: "smooth" });
    },
    toggleMobileMenu: function(force) {
      var el = document.getElementById("vb-mobile-drawer");
      if (!el) return;
      if (typeof force === "boolean") el.classList.toggle("is-open", force);
      else el.classList.toggle("is-open");
    },
    openCollection: function(kind, id) {
      var pool = kind === "mood" ? VB_COLLECTIONS.moods : (kind === "set" ? VB_COLLECTIONS.sets : VB_COLLECTIONS.categories);
      var found = pool.filter(function(c) { return c.id === id; })[0];
      if (!found) return;
      state.activeCollection = found;
      state.view = "collection";
      renderStage();
      window.scrollTo({ top: 0, behavior: "smooth" });
    },
    playCollection: function(kind, id) {
      var pool = kind === "mood" ? VB_COLLECTIONS.moods : (kind === "set" ? VB_COLLECTIONS.sets : VB_COLLECTIONS.categories);
      var found = pool.filter(function(c) { return c.id === id; })[0];
      var list = getSongsForCollection(kind, id);
      if (!found || list.length === 0) return;
      state.queue = list.slice();
      state.currentIndex = 0;
      state.activeCollectionTitle = found.title;
      startSongInternal(list[0]);
    },
    playFromList: function(listType, idx) {
      var list = listType === "viewing" ? (window._vbViewingList || state.queue) :
                 listType === "searchCurated" ? (window._vbSearchCurated || state.queue) :
                 listType === "searchLive" ? (window._vbSearchLive || state.queue) :
                 listType === "favorites" ? (window._vbFavList || state.favorites) : state.queue;
      if (!list || !list[idx]) return;
      state.queue = list.slice();
      state.currentIndex = idx;
      startSongInternal(list[idx]);
    },
    playFromQueueId: function(id) {
      for (var i = 0; i < state.queue.length; i++) {
        if (state.queue[i].id === id) {
          state.currentIndex = i;
          startSongInternal(state.queue[i]);
          return;
        }
      }
    },
    togglePlayPause: function() {
      var cur = state.queue[state.currentIndex];
      if (!cur) return;
      if (state.isPlaying) Engine.pause();
      else if (state.currentTime === 0) startSongInternal(cur);
      else Engine.resume();
    },
    nextSong: function(auto) {
      var idx = computeNextIndex(state.currentIndex, state.queue, state.prefs.shuffle, auto ? state.prefs.repeatMode : "all");
      if (idx === null) { Engine.pause(); return; }
      state.currentIndex = idx;
      startSongInternal(state.queue[idx], null, state.isPlaying && state.prefs.playbackMode === "preview-crossfade");
    },
    prevSong: function() {
      if (state.currentTime > 3) { Engine.seek(0); return; }
      state.currentIndex = (state.currentIndex - 1 + state.queue.length) % state.queue.length;
      startSongInternal(state.queue[state.currentIndex]);
    },
    seek: function(s) { Engine.seek(s); },
    setVolume: function(v) { state.prefs.volume = v; state.prefs.muted = false; saveJson(PREFS_KEY, state.prefs); Engine.applyVol(); },
    toggleMute: function() { state.prefs.muted = !state.prefs.muted; saveJson(PREFS_KEY, state.prefs); Engine.applyVol(); updatePlayerBarUI(); },
    toggleShuffle: function() { state.prefs.shuffle = !state.prefs.shuffle; saveJson(PREFS_KEY, state.prefs); updatePlayerBarUI(); renderStage(); },
    cycleRepeat: function() {
      state.prefs.repeatMode = state.prefs.repeatMode === "all" ? "one" : (state.prefs.repeatMode === "one" ? "off" : "all");
      saveJson(PREFS_KEY, state.prefs); updatePlayerBarUI();
    },
    setPlaybackMode: function(m) {
      state.prefs.playbackMode = m;
      saveJson(PREFS_KEY, state.prefs);
      if (state.isPlaying && state.queue[state.currentIndex]) startSongInternal(state.queue[state.currentIndex], m, false);
      else { updatePlayerBarUI(); renderStage(); }
    },
    togglePlaybackMode: function() {
      window.VB.setPlaybackMode(state.prefs.playbackMode === "preview-crossfade" ? "youtube" : "preview-crossfade");
    },
    setCrossfade: function(sec) { state.prefs.crossfadeSec = sec; saveJson(PREFS_KEY, state.prefs); updatePlayerBarUI(); },
    toggleHookStart: function() { state.prefs.hookStartEnabled = !state.prefs.hookStartEnabled; saveJson(PREFS_KEY, state.prefs); },
    toggleAutoSkip: function() { state.prefs.autoSkipUnavailable = !state.prefs.autoSkipUnavailable; saveJson(PREFS_KEY, state.prefs); },
    setVisStyle: function(st) { state.prefs.visStyle = st; saveJson(PREFS_KEY, state.prefs); renderStage(); },
    toggleDrawer: function() { state.drawerOpen = !state.drawerOpen; renderDrawer(); },
    dismissNotice: function() { state.unavailable = null; renderNotice(); },
    toggleFavoriteCurrent: function() {
      var cur = state.queue[state.currentIndex];
      if (!cur) return;
      var exists = state.favorites.some(function(f) { return f.id === cur.id; });
      state.favorites = exists ? state.favorites.filter(function(f) { return f.id !== cur.id; }) : [cur].concat(state.favorites);
      saveJson(FAVS_KEY, state.favorites);
      updatePlayerBarUI();
      if (state.view === "saved") renderStage();
    },
    toggleFavoriteById: function(id, listType) {
      var list = listType === "viewing" ? (window._vbViewingList || state.queue) :
                 listType === "searchCurated" ? (window._vbSearchCurated || state.queue) :
                 listType === "searchLive" ? (window._vbSearchLive || state.queue) :
                 listType === "favorites" ? state.favorites : state.queue;
      var song = list.filter(function(s) { return s.id === id; })[0];
      if (!song) return;
      var exists = state.favorites.some(function(f) { return f.id === id; });
      state.favorites = exists ? state.favorites.filter(function(f) { return f.id !== id; }) : [song].concat(state.favorites);
      saveJson(FAVS_KEY, state.favorites);
      renderStage();
      updatePlayerBarUI();
    },
    saveQueueFromInput: function(e) {
      e.preventDefault();
      var inp = document.getElementById("vb-save-name");
      var name = inp ? inp.value.trim() : "";
      if (!name || state.queue.length === 0) return;
      state.customPlaylists = [{ id: "pl-" + Date.now(), name: name, songs: state.queue.slice(), createdAt: new Date().toISOString() }].concat(state.customPlaylists);
      saveJson(PLAYLISTS_KEY, state.customPlaylists);
      renderStage();
    },
    playSavedPlaylist: function(id) {
      var pl = state.customPlaylists.filter(function(p) { return p.id === id; })[0];
      if (!pl || pl.songs.length === 0) return;
      state.queue = pl.songs.slice();
      state.currentIndex = 0;
      state.activeCollectionTitle = pl.name;
      startSongInternal(pl.songs[0]);
    },
    deleteSavedPlaylist: function(id) {
      state.customPlaylists = state.customPlaylists.filter(function(p) { return p.id !== id; });
      saveJson(PLAYLISTS_KEY, state.customPlaylists);
      renderStage();
    },
    addCustomAudioUrl: function(e) {
      e.preventDefault();
      var tEl = document.getElementById("vb-custom-title");
      var uEl = document.getElementById("vb-custom-url");
      var url = uEl ? uEl.value.trim() : "";
      if (!url) return;
      var title = (tEl && tEl.value.trim()) || "Custom Authorized Stream";
      var song = {
        id: "ext-" + Date.now(),
        title: title,
        artist: "External Authorized Stream",
        album: "Custom Audio",
        releaseYear: new Date().getFullYear(),
        genre: "Audio Stream",
        language: "Custom",
        moods: [], categories: [], sets: [],
        artworkUrl: "",
        durationSec: 180,
        sources: { itunesPreview: { previewUrl: url, officialUrl: url } }
      };
      state.queue.splice(state.currentIndex + 1, 0, song);
      if (tEl) tEl.value = "";
      if (uEl) uEl.value = "";
      state.currentIndex = state.currentIndex + 1;
      startSongInternal(song, "preview-crossfade", state.isPlaying);
    },
    onSearchInput: function(val) {
      state.searchQuery = val;
      if (searchTimer) window.clearTimeout(searchTimer);
      renderStage();
      var trimmed = val.trim();
      if (!trimmed) { state.liveSearchResults = []; state.searchLoading = false; return; }
      state.searchLoading = true;
      searchTimer = window.setTimeout(function() {
        var old = document.getElementById("vb-itunes-jsonp");
        if (old) old.remove();
        var sc = document.createElement("script");
        sc.id = "vb-itunes-jsonp";
        sc.src = "https://itunes.apple.com/search?term=" + encodeURIComponent(trimmed) + "&media=music&entity=song&limit=12&callback=_vbJsonpSearch";
        document.head.appendChild(sc);
      }, 320);
    }
  };

  renderStage();
  updatePlayerBarUI();
  startVisualizerLoop();
  enhanceBlogPostAudio();
})();
//
